source='''def _shape(points):
    min_r = min(r for r, c in points)
    min_c = min(c for r, c in points)
    return tuple(sorted((r - min_r, c - min_c) for r, c in points))


def transform(grid):
    frame = grid[0][0]
    width = 0
    while width < len(grid[0]) and grid[0][width] == frame:
        width += 1

    objects = {}
    for r, row in enumerate(grid):
        for c in range(width, len(row)):
            color = row[c]
            if color != 0 and color != frame:
                objects.setdefault(color, []).append((r, c))
    color_by_shape = {_shape(points): color for color, points in objects.items()}

    out = [row[:width] for row in grid]
    boundary_rows = [r for r, row in enumerate(grid) if all(row[c] == frame for c in range(width))]
    for top, bottom in zip(boundary_rows, boundary_rows[1:]):
        holes = [(r, c) for r in range(top + 1, bottom)
                 for c in range(1, width - 1) if grid[r][c] != frame]
        if holes:
            color = color_by_shape[_shape(holes)]
            for r, c in holes:
                out[r][c] = color
    return out
